#include <stdio.h>
#include <stdbool.h>

int count = 0;
void backtrack(int r, int n, bool cols[], bool d1[], bool d2[]) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++) {
        int id1 = r - c + n;
        int id2 = r + c;
        if (!cols[c] && !d1[id1] && !d2[id2]) {
            cols[c] = d1[id1] = d2[id2] = true;
            backtrack(r + 1, n, cols, d1, d2);
            cols[c] = d1[id1] = d2[id2] = false;
        }
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    bool cols[32] = {0}, d1[64] = {0}, d2[64] = {0};
    backtrack(0, n, cols, d1, d2);
    printf("%d\n", count);
    return 0;
}
